    (1699, "تَشَاءَمَ الطَّالِبُ مِنَ الِامْتِحَانِ الصَّعْبِ.", "Der Student war über die schwere Prüfung pessimistisch.", [("تَشَاءَمَ", "war pessimistisch"), ("الطَّالِبُ", "der Student"), ("مِنَ", "über"), ("الِامْتِحَانِ", "die Prüfung"), ("الصَّعْبِ", "schwere")]),
    (1700, "اِشْتَاقَ الْوَلَدُ إِلَى أُمِّهِ فِي السَّفَرِ.", "Der Junge sehnte sich auf der Reise nach seiner Mutter.", [("اِشْتَاقَ", "sehnte sich"), ("الْوَلَدُ", "der Junge"), ("إِلَى", "nach"), ("أُمِّهِ", "seiner Mutter"), ("فِي", "auf"), ("السَّفَرِ", "der Reise")]),
    (1700, "اِشْتَاقَ الْمُسَافِرُ إِلَى وَطَنِهِ بَعْدَ السَّنَوَاتِ.", "Der Reisende sehnte sich nach Jahren nach seiner Heimat.", [("اِشْتَاقَ", "sehnte sich"), ("الْمُسَافِرُ", "der Reisende"), ("إِلَى", "nach"), ("وَطَنِهِ", "seiner Heimat"), ("بَعْدَ", "nach"), ("السَّنَوَاتِ", "den Jahren")]),
    (1700, "اِشْتَاقَ النَّاسُ إِلَى السَّلَامِ بَعْدَ الْحَرْبِ.", "Die Leute sehnten sich nach dem Krieg nach dem Frieden.", [("اِشْتَاقَ", "sehnten sich"), ("النَّاسُ", "die Leute"), ("إِلَى", "nach"), ("السَّلَامِ", "dem Frieden"), ("بَعْدَ", "nach"), ("الْحَرْبِ", "dem Krieg")]),
